mapper.update:
UPDATE activity_registration
SET status       = 2,
    cancelled_at = NOW()
WHERE activity_id = #{activityId}
  AND user_id = #{userId}
  AND status = 1

mapper.select:
SELECT id, activity_id, user_id, status, registered_at, cancelled_at, created_at, updated_at
FROM activity_registration
WHERE activity_id = #{activityId}
  AND user_id = #{userId}
